#!/usr/bin/env python3
"""Read-only C2 claim-fit review; every generated byte stays in this seat's scratch/evidence."""
import concurrent.futures
import hashlib
import json
import os
from pathlib import Path
import subprocess

SCRATCH = Path('/fast/scratch/hyaku/chousa-r34-a2/w2/CritC2AxisFit')
FROZEN = SCRATCH / 'frozen'
EVIDENCE = Path('/home/vgpnk/Projects/shokunin/chousa-shokunin/.ufo/waves/round-34/w2a2/CritC2AxisFit')
ENV = {k: v for k, v in os.environ.items() if not k.startswith('CHOUSA_') and k not in ('GIT_DIR', 'GIT_WORK_TREE', 'GIT_INDEX_FILE')}
ENV.update(C2_TMP=str(SCRATCH), C1_TMP=str(SCRATCH), TMPDIR=str(SCRATCH), PYTHONDONTWRITEBYTECODE='1')
records = []

def digest(p):
    return hashlib.sha256(Path(p).read_bytes()).hexdigest()

def run(name, argv, cwd, limit=180):
    command = ['timeout', str(limit) + 's', *map(str, argv)]
    p = subprocess.Popen(command, cwd=cwd, env=ENV, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    out, err = p.communicate(timeout=limit + 10)
    if len(out) > 524288 or len(err) > 524288:
        raise RuntimeError('bounded capture exceeded for ' + name)
    for suffix, data in [('stdout.txt', out), ('stderr.txt', err)]:
        (EVIDENCE / (name + '.' + suffix)).write_bytes(data)
    result = {'name': name, 'argv': command, 'cwd': str(cwd), 'pid': p.pid, 'rc': p.returncode,
              'stdout_path': str(EVIDENCE / (name + '.stdout.txt')), 'stdout_sha256': hashlib.sha256(out).hexdigest(),
              'stderr_path': str(EVIDENCE / (name + '.stderr.txt')), 'stderr_sha256': hashlib.sha256(err).hexdigest()}
    records.append(result)
    return result, out.decode(), err.decode()

base = subprocess.run(['timeout', '30s', 'git', '-C', str(FROZEN), 'show', 'bf7c931a:tools/research-gate.sh'],
                      env=ENV, capture_output=True, check=True).stdout
assert len(base) < 1048576
basegate = SCRATCH / 'base-research-gate.sh'
basegate.write_bytes(base)
gate = FROZEN / 'tools/research-gate.sh'
assert digest(gate) == 'a6307edf687ac0fb1b0b08bf7f0518b3fbc310fa9924b970aa3654612562995b'
assert digest(basegate) == '772a1d8e4d94dbf3a44a64bf850b1324e51546eeb62abcd7b3ec585f0e003e58'

jobs = [('c2-after-s6701309', gate, 6701309), ('c2-after-s6701321', gate, 6701321),
        ('c2-before-s6701309', basegate, 6701309)]
def counter(job):
    name, selected, seed = job
    return run(name, ['python3', FROZEN / 'corpus/evidence/round34/c2-count.py', '--gate', selected,
                      '--seed', seed, '--receipt', EVIDENCE / (name + '.json')], FROZEN)
with concurrent.futures.ThreadPoolExecutor(max_workers=3) as ex:
    results = list(ex.map(counter, jobs))
for r, out, err in results:
    print(r['name'], 'pid=' + str(r['pid']), 'rc=' + str(r['rc']), out.splitlines()[0])

fixture = SCRATCH / 'overlap-fixture'
fixture.mkdir(exist_ok=True)
span = 'a\n' * 16382 + 'a'
assert len(span.encode()) == 32765
sources = {'glued.md': 'x' + span + '\na\n', 'both-valid.md': ' ' + span + '\na\n'}
for name, text in sources.items():
    (fixture / name).write_text(text)
line2 = str(2) + '-' + str(2 + span.count('\n'))
claims = [dict(id='OVERLAP_GLUE', source='glued.md', span=span, expect='supported'),
          dict(id='OVERLAP_LINE', source='both-valid.md', span=span, expect='supported', line=line2)]
(fixture / 'claims.jsonl').write_text(''.join(json.dumps(c) + '\n' for c in claims))
oracle = []
for c in claims:
    text = sources[c['source']]
    starts = [i for i in range(len(text) - len(span) + 1) if text.startswith(span, i)]
    valid = [i for i in starts if (i == 0 or text[i-1].isspace()) and (i+len(span) == len(text) or text[i+len(span)].isspace())]
    lines = [[text.count('\n', 0, i)+1, text.count('\n', 0, i)+1+span.count('\n')] for i in valid]
    assert 3 in valid
    assert [2, 16384] in lines
    oracle.append({'id': c['id'], 'span_bytes': len(span.encode()), 'exact_offsets': starts,
                   'valid_offsets': valid, 'valid_line_ranges': lines, 'line': c.get('line'),
                   'expected': 'supported', 'source_sha256': digest(fixture / c['source'])})
(EVIDENCE / 'overlap-oracle.json').write_text(json.dumps(oracle, indent=2) + '\n')
r, out, err = run('overlap-landed', ['bash', gate, 'verify-claims', fixture / 'claims.jsonl', '--root', fixture], fixture)
print(r['name'], 'pid=' + str(r['pid']), 'rc=' + str(r['rc']))
print(out)

r, out, err = run('audit-frozen', ['python3', FROZEN / 'corpus/evidence/round34/self-audit.py', '--lane', FROZEN], FROZEN)
print(r['name'], 'pid=' + str(r['pid']), 'rc=' + str(r['rc']), '\n'.join(out.splitlines()[-2:]))

catalogue = []
for path in sorted((FROZEN / '.ufo/waves/round-34/measure-a2').glob('c2-*.json')):
    r = json.loads(path.read_text())
    catalogue.append({'path': str(path.relative_to(FROZEN)), 'sha256': digest(path),
                      **{k: r[k] for k in ['counter_sha256', 'gate_sha256', 'seed', 'total', 'matched', 'label', 'predicate_holds', 'gate_rc']}})
(EVIDENCE / 'committed-receipts.json').write_text(json.dumps(catalogue, indent=2) + '\n')
(EVIDENCE / 'commands.json').write_text(json.dumps({'runner_pid': os.getpid(), 'snapshot': '707da8184a0fc4d10ab3f17271556cdf364f0af5',
              'gate_sha256': digest(gate), 'base_gate_sha256': digest(basegate), 'probe_sha256': digest(__file__), 'runs': sorted(records, key=lambda r: r['name'])}, indent=2) + '\n')
